// Configuración por entidad: tabla destino, columnas requeridas y su tipo.
// Ajusta esta sección al esquema real de tu base de datos.
// Un solo cargador reemplaza los 5+ workflows "Cargue masivo de X" originales.
const ENTITY_CONFIGS = {
  USUARIOS: {
    table: 'dbo.Usuarios',
    requiredFields: ['Login', 'Nombre', 'Email'],
    fieldTypes: { Login: 'string', Nombre: 'string', Email: 'string' }
  },
  MEDICAMENTOS: {
    table: 'dbo.Medicamentos',
    requiredFields: ['Codigo', 'Nombre', 'Presentacion'],
    fieldTypes: { Codigo: 'string', Nombre: 'string', Presentacion: 'string' }
  },
  MEDICAMENTOS_COMERCIALES: {
    table: 'dbo.MedicamentosComerciales',
    requiredFields: ['Codigo', 'NombreComercial'],
    fieldTypes: { Codigo: 'string', NombreComercial: 'string' }
  },
  INSUMOS_COMERCIALES: {
    table: 'dbo.InsumosComerciales',
    requiredFields: ['Codigo', 'Nombre'],
    fieldTypes: { Codigo: 'string', Nombre: 'string' }
  },
  INSUMOS_GENERICOS: {
    table: 'dbo.InsumosGenericos',
    requiredFields: ['Codigo', 'Nombre'],
    fieldTypes: { Codigo: 'string', Nombre: 'string' }
  },
  INVENTARIO: {
    table: 'dbo.Inventario',
    requiredFields: ['CodigoItem', 'Cantidad', 'Sede'],
    fieldTypes: { CodigoItem: 'string', Cantidad: 'number', Sede: 'string' }
  },
  CONTRATOS: {
    table: 'dbo.Contratos',
    requiredFields: ['NumeroContrato', 'Entidad'],
    fieldTypes: { NumeroContrato: 'string', Entidad: 'string' }
  },
  ASOCIACION_SEDES_CONTRATOS: {
    table: 'dbo.AsociacionSedesContratos',
    requiredFields: ['NumeroContrato', 'Sede'],
    fieldTypes: { NumeroContrato: 'string', Sede: 'string' }
  },
  PROCEDIMIENTOS: {
    table: 'dbo.Procedimientos',
    requiredFields: ['Codigo', 'Nombre'],
    fieldTypes: { Codigo: 'string', Nombre: 'string' }
  },
  MANUAL_TARIFARIO: {
    table: 'dbo.ManualTarifario',
    requiredFields: ['Codigo', 'Valor'],
    fieldTypes: { Codigo: 'string', Valor: 'number' }
  }
};

const entity = ($('When called by Main Router').first().json.entity || '').toUpperCase();
const config = ENTITY_CONFIGS[entity];
if (!config) {
  throw new Error(`Entidad '${entity}' no soportada. Disponibles: ${Object.keys(ENTITY_CONFIGS).join(', ')}`);
}

const items = $input.all();
const results = items.map((item, idx) => {
  const row = item.json;
  const errors = [];
  for (const field of config.requiredFields) {
    if (row[field] === undefined || row[field] === null || row[field] === '') {
      errors.push(`Falta el campo requerido '${field}'`);
    }
  }
  for (const [field, type] of Object.entries(config.fieldTypes)) {
    if (row[field] === undefined) continue;
    if (type === 'number' && isNaN(Number(row[field]))) {
      errors.push(`El campo '${field}' debe ser numérico`);
    }
  }
  return {
    json: {
      rowIndex: idx + 2, // +2: encabezado + índice base 1
      table: config.table,
      data: row,
      valid: errors.length === 0,
      errors
    }
  };
});

return results;
